{
  "name": "dsh-opencode-palette",
  "version": "2.1.12",
  "description": "让 DeepSeek Harness 穿上 38 款经典皮肤——东京的霓虹夜色、德古拉的暗红月光、复古工坊的暖黄灯火、黑客帝国的数字雨、玫瑰松林间的风……一键换肤，即点即换，重启不丢。38 legendary skins for DeepSeek Harness — tokyonight's neon dusk, dracula's crimson moon, gruvbox's retro glow, the matrix's digital rain, rose-pine's rosewood calm… one click, instant, persisted.",
  "type": "module",
  "main": "lib/index.js",
  "exports": {
    ".": "./lib/index.js",
    "./client": "./lib/client.js",
    "./cordis.patch.yml": "./cordis.patch.yml",
    "./package.json": "./package.json"
  },
  "files": [
    "lib",
    "cordis.patch.yml"
  ],
  "keywords": [
    "dsh",
    "deepseek-harness",
    "plugin",
    "theme",
    "opencode",
    "tui",
    "dark",
    "multi-theme"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/FeatherHunter/dsh-opencode-palette.git"
  },
  "homepage": "https://github.com/FeatherHunter/dsh-opencode-palette",
  "bugs": {
    "url": "https://github.com/FeatherHunter/dsh-opencode-palette/issues"
  },
  "dependencies": {
    "dsh-log": "0.3.4",
    "dsh-plugin-update": "0.18.39"
  },
  "engines": {
    "node": ">=22.18.0",
    "dsh": ">=0.2.0-rc.1"
  },
  "dsh": {
    "bundle": {
      "patch": "./cordis.patch.yml"
    },
    "client": {
      "platform": "web",
      "immediately": true,
      "inject": [
        "@deepseek-ai/dsh-client-ui-theme"
      ]
    }
  },
  "license": "MIT"
}
